/**
 * 负责机械狼原体、复制技能与已选模式范围，输入保原生命／槽／来源，输出为复验和实际本夜提交记录。
 * 原阵营表达式晚查当前值，不新增 Camp 引用撤权；替换模式／槽仍不能复用原学习或刀权。
 * 已付技能谓词保原资源独立性，不将行动退休混入原体复验或删除知识数据。
 */
import type {
  MechanicalMode,
  MechanicalReadState as MechanicalState,
  MechanicalReadSkill as MechanicalSkill,
} from "@ai-werewolf-arena/game-contract";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { getMechanicalState } from "./state";

export interface MechanicalOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: MechanicalState;
  readonly life: NightLifeScope;
  isCurrent(): boolean;
}

/** 仅运行引用，不序列化进玩家 DTO 或 Tape，也不是状态副本的授权。 */
export function captureMechanicalOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): MechanicalOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role);
  const state = getMechanicalState(role);
  const life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.MechanicalWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    isCurrent: () =>
      phaseCurrent() &&
      world.getComponent(actorId, COMPONENT.Role) === role &&
      role.role === Role.MechanicalWolf &&
      world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
      role.privateState === privateState &&
      getMechanicalState(role) === state &&
      livingNightLife(world, life),
  };
}

/** 已提交效果绑定原学习和所选模式；不按已经消费的库存取消效果。 */
export function bindMechanicalSkill(
  scope: MechanicalOwnerScope,
  day: number,
): {
  readonly skill: MechanicalSkill;
  isCurrent(): boolean;
} | null {
  const learned = scope.state.learned,
    mode = scope.state.mode;
  if (
    day < 2 ||
    !scope.isCurrent() ||
    !hasCurrentMechanicalMode(scope.world, scope.role, "skill") ||
    !learned ||
    learned.readyOnNight > day ||
    !mode ||
    mode.day !== day ||
    mode.kind !== "skill"
  )
    return null;
  const skill = learned.skill,
    kind = skill.kind;
  return {
    skill,
    isCurrent: () =>
      scope.isCurrent() &&
      hasCurrentMechanicalMode(scope.world, scope.role, "skill") &&
      scope.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      scope.state.mode === mode &&
      mode.day === day &&
      mode.kind === "skill" &&
      learned.readyOnNight <= day,
  };
}

interface MechanicalModeScope {
  readonly owner: MechanicalOwnerScope;
  readonly mode: NonNullable<MechanicalState["mode"]>;
  readonly kind: MechanicalMode;
}
const modes = new WeakMap<
  World,
  { readonly day: number; readonly actors: Map<EntityId, MechanicalModeScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function hasMechanicalNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}
export function recordMechanicalNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}

/** 接受模式选择或原明确 skill 默认后才保存本夜 authority，失败不重建旧范围。 */
export function recordMechanicalModeScope(
  world: World,
  scope: MechanicalOwnerScope,
  day: number,
): boolean {
  const mode = scope.state.mode;
  if (scope.world !== world || day < 2 || !scope.isCurrent() || !mode || mode.day !== day)
    return false;
  let night = modes.get(world);
  if (night && night.day > day) return false;
  if (!night || night.day !== day) {
    night = { day, actors: new Map() };
    modes.set(world, night);
  }
  if (night.actors.has(scope.actorId)) return false;
  night.actors.set(scope.actorId, { owner: scope, mode, kind: mode.kind });
  return true;
}

/** 只读刀权查询；序列化模式事实不能恢复已经失效的原 authority。 */
export function hasCurrentMechanicalMode(
  world: World,
  role: RoleComponent,
  expectedKind: MechanicalMode,
): boolean {
  const night = modes.get(world);
  if (!night) return false;
  for (const { owner, mode, kind } of night.actors.values()) {
    if (
      owner.role === role &&
      owner.isCurrent() &&
      owner.state.mode === mode &&
      mode.day === night.day &&
      mode.kind === kind &&
      kind === expectedKind
    )
      return true;
  }
  return false;
}
export function hasCurrentMechanicalKillMode(world: World, role: RoleComponent): boolean {
  return hasCurrentMechanicalMode(world, role, "kill");
}

/**
 * 负责机械狼模式、学习、复制技能和额外刀阶段。
 * 输入为原 owner/mode/技能 scope 与已验证工具；输出为原已付事实及有来源的盾、刀、失败、原毒 intent。
 * intent 只复用原捕获 life/day/目标，不增加 World、时钟或 RNG 读取；原付款和记录次序保持。
 * 有效性仍由原 callback 决定，不合并不同技能资源或失败规则；运行时来源不写入归档。
 */
import {
  recordMechanicalInspection,
  consumeMechanicalPoison,
  closeMechanicalExtraKnife,
} from "./state";

import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife, mechanicalNightIntent, originalPoisonIntent } from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { resolveInspection } from "../inspection";
import { canMechanicalKnife } from "./inheritance";
import {
  bindMechanicalSkill,
  captureMechanicalOwner,
  recordMechanicalModeScope,
  recordMechanicalNightCommit,
} from "./night_scope";
import {
  advanceMechanicalNight,
  canMechanicalMimic,
  canSelectMechanicalMode,
  chooseMechanicalGuard,
  closeMechanicalMimic,
  closeMechanicalSkill,
  learnMechanicalRole,
  mechanicalSkillForNight,
  selectMechanicalMode,
  canMechanicalExtraKnife,
} from "./state";

function owners(ctx: NightStageContext) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureMechanicalOwner(ctx.world, id, ctx.isCurrent);
    return owner ? [owner] : [];
  });
}
function targets(ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) {
  return new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
}
function effects(ctx: NightStageContext) {
  return (ctx.state.mechanicalEffects ??= { shields: [], attacks: [], failures: [] });
}

const modeStage: NightStageHandler = {
  id: "mechanical_mode",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      if (!owner.isCurrent()) continue;
      advanceMechanicalNight(owner.state, day);
      if (!canSelectMechanicalMode(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canSelectMechanicalMode(owner.state, day)) break;
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["mechanical_mode"], {
            stage: "mechanical_mode",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!owner.isCurrent() || !canSelectMechanicalMode(owner.state, day)) break;
        let chosenMode: "skill" | "kill" = "skill";
        if (action !== null) {
          if (action.name !== "mechanical_mode") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!owner.isCurrent() || !valid.ok || valid.sanitizedCall?.name !== "mechanical_mode")
            continue;
          chosenMode = valid.sanitizedCall.args.mode;
        }
        if (!selectMechanicalMode(owner.state, day, chosenMode)) break;
        recordMechanicalModeScope(ctx.world, owner, day);
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_mode_selected",
          payload: { actorId: owner.actorId, day, mode: owner.state.mode!.kind },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canSelectMechanicalMode(owner.state, day))
        throw new Error("mechanical_mode_valid_action_missing");
    }
  },
};

const mimicStage: NightStageHandler = {
  id: "mechanical_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      if (!canMechanicalMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canMechanicalMimic(owner.state, day)) break;
        const candidates = targets(ctx, owner.actorId, true);
        const targetRoles = new Map(
          [...candidates.keys()].map((id) => {
            const role = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component: role, role: role.role }] as const;
          }),
        );
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["mimic_role"], {
                stage: "mechanical_mimic",
                requiresAction: false,
                ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canMechanicalMimic(owner.state, day)) break;
        if (action === null) {
          closeMechanicalMimic(owner.state, day);
          recordMechanicalNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "mimic_role") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "mimic_role" ||
          !canMechanicalMimic(owner.state, day)
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          targetRole = targetRoles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !targetRole ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== targetRole.component ||
          targetRole.component.role !== targetRole.role
        )
          continue;
        if (!learnMechanicalRole(owner.state, targetId, targetRole.role, day)) continue;
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_mimicked",
          payload: {
            actorId: owner.actorId,
            day,
            targetId,
            role: owner.state.learned!.role,
            readyOnNight: day + 1,
          },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canMechanicalMimic(owner.state, day))
        throw new Error("mechanical_mimic_valid_action_missing");
    }
  },
};

const skillStage: NightStageHandler = {
  id: "mechanical_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      const skill = mechanicalSkillForNight(owner.state, day),
        bound = bindMechanicalSkill(owner, day);
      if (!skill || !bound || !["inspection", "poison", "guard"].includes(skill.kind)) continue;
      if (skill.kind === "poison" && skill.remaining === 0) continue;
      const tool: ToolName =
        skill.kind === "inspection"
          ? "mechanical_inspect"
          : skill.kind === "poison"
            ? "mechanical_poison"
            : "mechanical_guard";
      const current = () =>
        bound.isCurrent() &&
        mechanicalSkillForNight(owner.state, day) === skill &&
        (skill.kind !== "poison" || skill.remaining > 0);
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, skill.kind === "inspection");
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "mechanical_skill",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        if (action === null) {
          closeMechanicalSkill(owner.state, day);
          recordMechanicalNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (
          !["mechanical_inspect", "mechanical_poison", "mechanical_guard"].includes(call.name) ||
          !("target_id" in call.args)
        )
          continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "mechanical_inspect" && skill.kind === "inspection" && target) {
          const result = resolveInspection(ctx.world, target.id, "role", ctx.roleCatalog);
          if (!result || !current() || !livingNightLife(ctx.world, target)) continue;
          recordMechanicalInspection(skill, day, target, result);
          ctx.events.push({
            timestamp: Date.now(),
            type: "role_inspected",
            payload: { actorId: owner.actorId, day, targetId: target.id, result: { ...result } },
          });
        } else if (call.name === "mechanical_poison" && skill.kind === "poison" && target) {
          (ctx.state.poisonClaims ??= []).push(originalPoisonIntent({ source: owner.life, target }, {
            family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
            requestedTargetId: targetId, abilityId: "learned:mechanical",
          }));
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          consumeMechanicalPoison(skill);
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "mechanical_guard" && skill.kind === "guard") {
          const { failed } = chooseMechanicalGuard(skill, targetId, day);
          if (failed)
            effects(ctx).failures.push(mechanicalNightIntent("mechanical-failure", {
              actorId: owner.actorId,
              target: owner.life,
              isCurrent: bound.isCurrent,
            }, { family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
              requestedTargetId: targetId, abilityId: "learned:mechanical" }));
          else if (target)
            effects(ctx).shields.push(mechanicalNightIntent("mechanical-shield", {
              actorId: owner.actorId,
              target,
              isCurrent: bound.isCurrent,
            }, { family: "mechanical", day, stage: "mechanical_skill", actorLife: owner.life,
              requestedTargetId: targetId, abilityId: "learned:mechanical" }));
          ctx.events.push({
            timestamp: Date.now(),
            type: "mechanical_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId, failed },
          });
        } else continue;
        closeMechanicalSkill(owner.state, day);
        recordMechanicalNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("mechanical_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "mechanical_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx)) {
      const learned = owner.state.learned,
        mode = owner.state.mode;
      if (learned?.skill.kind !== "wolf" || !mode) continue;
      const skill = learned.skill;
      const effectCurrent = () =>
        owner.isCurrent() &&
        owner.state.learned === learned &&
        learned.skill === skill &&
        skill.kind === "wolf" &&
        owner.state.mode === mode &&
        mode.day === day &&
        mode.kind === "kill" &&
        canMechanicalKnife(owner.role, ctx.world, () => ctx.world.getComponent(owner.actorId, COMPONENT.Camp));
      const current = () => effectCurrent() && canMechanicalExtraKnife(owner.state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["mechanical_attack"], {
            stage: "mechanical_attack",
            requiresAction: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "mechanical_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "mechanical_attack")
            continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (target)
          effects(ctx).attacks.push(mechanicalNightIntent("mechanical-attack", { actorId: owner.actorId, target, isCurrent: effectCurrent }, {
            family: "mechanical", day, stage: "mechanical_attack", actorLife: owner.life,
            requestedTargetId: targetId, abilityId: "learned:mechanical",
          }));
        closeMechanicalExtraKnife(skill, target);
        recordMechanicalNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "mechanical_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("mechanical_attack_valid_action_missing");
    }
  },
};

export const MECHANICAL_NIGHT_STAGES = [modeStage, mimicStage, skillStage, attackStage];

/**
 * 负责机械狼工具的本夜模式与行动资格校验。输入为原工具参数、角色状态及可信上下文，输出原规则拒绝或通过。
 * 预检不等于复制、付款或落效果，原体与能力资源仍由机械机制持有并在提交时复验。
 */
import { MECHANICAL_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { ToolRule, ToolRuleMap } from "../../validation/contracts";
import { isAliveTarget } from "../../validation/contracts";
import { canMechanicalKnife } from "./inheritance";
import { hasCurrentMechanicalMode } from "./night_scope";
import {
  canMechanicalMimic,
  canSelectMechanicalMode,
  canMechanicalExtraKnife,
  getMechanicalState,
  mechanicalSkillForNight,
} from "./state";

const validateMechanical: ToolRule = ({ world, actorId, role, day, phase, toolCall }) => {
  const state = getMechanicalState(role);
  if (role.role !== Role.MechanicalWolf || world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf || !state || day === undefined)
    return { code: RuleError.MechanicalUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "mechanical_mode") {
    return canSelectMechanicalMode(state, day) && ["kill", "skill"].includes(toolCall.args.mode)
      ? null
      : { code: RuleError.MechanicalUnavailable };
  }
  if (toolCall.name === "mimic_role") {
    if (!canMechanicalMimic(state, day)) return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_attack") {
    if (!canMechanicalKnife(role, world, () => world.getComponent(actorId, COMPONENT.Camp)) || !canMechanicalExtraKnife(state, day))
      return { code: RuleError.MechanicalUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  const skill = hasCurrentMechanicalMode(world, role, "skill")
    ? mechanicalSkillForNight(state, day)
    : undefined;
  if (toolCall.name === "mechanical_inspect" && skill?.kind === "inspection") {
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_poison" && skill?.kind === "poison" && skill.remaining > 0) {
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  if (toolCall.name === "mechanical_guard" && skill?.kind === "guard") {
    // 连续守护同编号仍是合法提交；惩罚在黎明生效，不能在预检阶段代付或拒绝。
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.MechanicalTarget };
  }
  return { code: RuleError.MechanicalUnavailable };
};

export { MECHANICAL_TOOL_NAMES } from "./tool_names";
export const MECHANICAL_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  MECHANICAL_TOOL_NAMES.map((name) => [name, validateMechanical]),
);

/**
 * 负责觉醒隐狼本夜原体、学习与镜像范围捕获；输入保原能力／Role／生命引用，输出为复验与本夜记录。
 * 原阵营表达式晚查当前值，不新增 Camp 引用撤权；槽／来源／生命替换仍按原规则失效。
 * 已付 skill／mirror 原谓词不因行动墓碑失效；不以合法数据副本授予原捕获权限。
 */
import type {
  AwakenedReadState as AwakenedState,
  AwakenedReadActiveSkill as AwakenedActiveSkill,
} from "@ai-werewolf-arena/game-contract";

import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Camp, Role, type EntityId } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  type NightLifeScope,
} from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import { awakenedSkillForNight, getAwakenedState } from "./state";
import { findNightAbility, type NightAbilityReadView } from "../abilities";

export interface AwakenedOwnerScope {
  readonly world: World;
  readonly actorId: EntityId;
  readonly role: RoleComponent;
  readonly state: AwakenedState;
  readonly life: NightLifeScope;
  isCurrent(allowFirstDeath?: boolean): boolean;
}
export function captureAwakenedOwner(
  world: World,
  actorId: EntityId,
  phaseCurrent: () => boolean,
): AwakenedOwnerScope | null {
  const role = world.getComponent(actorId, COMPONENT.Role),
    state = getAwakenedState(role),
    life = captureNightLife(world, actorId);
  if (
    !phaseCurrent() ||
    !role ||
    role.role !== Role.AwakenedHiddenWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    !life
  )
    return null;
  const privateState = role.privateState;
  return {
    world,
    actorId,
    role,
    state,
    life,
    isCurrent: (allowFirstDeath = false) => {
      const original =
        world.getComponent(actorId, COMPONENT.Alive) === life.life &&
        aliveLifeVersion(life.life) ===
          life.version + (allowFirstDeath && !life.life.alive ? 1 : 0);
      return (
        phaseCurrent() &&
        world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.AwakenedHiddenWolf &&
        world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
        role.privateState === privateState &&
        getAwakenedState(role) === state &&
        original &&
        (allowFirstDeath || life.life.alive)
      );
    },
  };
}
/** 绑定已付事实，复验原学习引用，不读已关闭槽或已消费瓶／刀来取消效果。 */
export function bindAwakenedSkill(
  owner: AwakenedOwnerScope,
  day: number,
): { readonly skill: AwakenedActiveSkill; isCurrent(allowFirstDeath?: boolean): boolean } | null {
  const learned = owner.state.learned,
    skill = awakenedSkillForNight(owner.state, day);
  if (
    !owner.isCurrent() ||
    !learned ||
    !skill ||
    learned.activationNight === null ||
    learned.activeFromNight === null
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    kind = skill.kind;
  return {
    skill,
    isCurrent: (allowFirstDeath = false) =>
      owner.isCurrent(allowFirstDeath) &&
      owner.state.learned === learned &&
      learned.skill === skill &&
      skill.kind === kind &&
      learned.targetId === targetId &&
      learned.role === role &&
      learned.day === learnedDay &&
      learned.activationNight === activationNight &&
      learned.activeFromNight === activeFromNight,
  };
}
/** 仅觉醒原生镜像依赖本学习；独立赠予／复制实例不附加这项来源关系。 */
export function captureAwakenedMirrorScope(
  world: World,
  actorId: EntityId,
  ability: NightAbilityReadView<"role_check">,
  day: number,
  phaseCurrent: () => boolean,
): (() => boolean) | null {
  const owner = captureAwakenedOwner(world, actorId, phaseCurrent),
    learned = owner?.state.learned,
    skill = learned?.skill;
  if (
    !owner ||
    currentAwakenedNight(world, owner.role) !== day ||
    !learned ||
    learned.role !== Role.MirrorGirl ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    day < learned.activeFromNight ||
    skill?.kind !== "inspection" ||
    skill.abilityId !== ability.id
  )
    return null;
  const { targetId, role, day: learnedDay, activationNight, activeFromNight } = learned,
    abilityId = skill.abilityId;
  return () =>
    owner.isCurrent() &&
    currentAwakenedNight(world, owner.role) === day &&
    owner.state.learned === learned &&
    learned.skill === skill &&
    skill.kind === "inspection" &&
    skill.abilityId === abilityId &&
    learned.targetId === targetId &&
    learned.role === role &&
    learned.day === learnedDay &&
    learned.activationNight === activationNight &&
    learned.activeFromNight === activeFromNight &&
    findNightAbility(owner.role, "role_check", abilityId) === ability;
}
const nights = new WeakMap<
  World,
  { day: number; owners: Map<RoleComponent, AwakenedOwnerScope> }
>();
const committed = new WeakMap<World, Set<number>>();
export function beginAwakenedNight(
  world: World,
  day: number,
  owners: readonly AwakenedOwnerScope[],
): void {
  if (hasAwakenedNightCommit(world, day)) throw new Error("awakened_night_reentry_after_commit");
  if (nights.get(world)?.day === day) throw new Error("awakened_night_reentry_after_commit");
  if ((nights.get(world)?.day ?? day) > day) throw new Error("awakened_night_clock_regressed");
  const currentOwners = owners.filter((owner) => owner.world === world && owner.isCurrent());
  nights.set(world, { day, owners: new Map(currentOwners.map((owner) => [owner.role, owner])) });
  // 建立本夜原体 authority 本身就是已提交前缀；仅继承刀或没有复制主动技能的夜也保此记录。
  if (currentOwners.length) recordAwakenedNightCommit(world, day);
}
export function currentAwakenedNight(world: World, role: RoleComponent): number | null {
  const night = nights.get(world),
    owner = night?.owners.get(role);
  return night && owner?.isCurrent() && livingNightLife(world, owner.life) ? night.day : null;
}
export function recordAwakenedNightCommit(world: World, day: number): void {
  const days = committed.get(world) ?? new Set<number>();
  days.add(day);
  committed.set(world, days);
}
export function hasAwakenedNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

/**
 * 负责觉醒隐狼开夜、学习、技能、额外刀和激活阶段。
 * 输入为原 native/copy scope 与已验证工具；输出为原已付事实及有来源的盾、刀和原毒 intent。
 * 复用原捕获 life/day/目标，保留付款位置以及允许首次死亡的 paid callback。
 * 不以新来源数据替代资格、库存或重试规则，不恢复撤销的原 owner，不改变阶段优先级或归档。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import { Phase, StatusMark, type EntityId, type ToolName } from "../../../../core/domain/model";
import {
  captureNightLife,
  livingNightLife,
  awakenedNightIntent,
  originalPoisonIntent,
} from "../../../../core/domain/night_effects";
import type { NightStageContext, NightStageHandler } from "../../stages/night/contracts";
import { allNightAbilities, findNightAbility, retiredNightAbilityIds } from "../abilities";
import { installNativeAbility } from "../ability_changes";
import { setNightAbilityStartDay } from "../abilities";
import { canAwakenedKnife } from "./inheritance";
import {
  beginAwakenedNight,
  bindAwakenedSkill,
  captureAwakenedOwner,
  currentAwakenedNight,
  recordAwakenedNightCommit,
} from "./night_scope";
import {
  activateAwakenedLearning,
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  chooseAwakenedAttack,
  chooseAwakenedGuard,
  closeAwakenedMimic,
  learnAwakenedRole,
  skipAwakenedSkill,
  useAwakenedPoison,
} from "./state";

function owners(ctx: NightStageContext, day: number, opening = false) {
  return ctx.world.getAliveEntityIds().flatMap((id) => {
    const owner = captureAwakenedOwner(
      ctx.world,
      id,
      () => ctx.isCurrent() && ctx.currentDay() === day,
    );
    return owner && (opening || currentAwakenedNight(ctx.world, owner.role) === day) ? [owner] : [];
  });
}
const targets = (ctx: NightStageContext, actorId: EntityId, excludeSelf: boolean) =>
  new Map(
    ctx.world
      .getAliveEntityIds()
      .filter((id) => !excludeSelf || id !== actorId)
      .map((id) => [id, captureNightLife(ctx.world, id)!] as const),
  );
const effects = (ctx: NightStageContext) =>
  (ctx.state.awakenedEffects ??= { shields: [], attacks: [] });
const retry = (attempt: number) => (attempt ? { retry_attempt: attempt, retry_max: 2 } : {});

const openingStage: NightStageHandler = {
  id: "awakened_opening",
  priority: 250,
  async execute(ctx) {
    const day = ctx.currentDay();
    beginAwakenedNight(ctx.world, day, owners(ctx, day, true));
  },
};
const mimicStage: NightStageHandler = {
  id: "awakened_mimic",
  priority: 580,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      if (!canAwakenedMimic(owner.state, day)) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        const candidates = targets(ctx, owner.actorId, true);
        const roles = new Map(
          [...candidates.keys()].map((id) => {
            const component = ctx.world.getComponent(id, COMPONENT.Role)!;
            return [id, { component, role: component.role, camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp }] as const;
          }),
        );
        const action = candidates.size
          ? await ctx.actionProvider.getAction(
              ctx.makeRequest(owner.actorId, ["awakened_mimic"], {
                stage: "awakened_mimic",
                requiresAction: false,
                action_failure_policy: "error",
                allow_fallback: false,
                ...retry(attempt),
              }),
            )
          : null;
        if (!owner.isCurrent() || !canAwakenedMimic(owner.state, day)) break;
        if (action === null) {
          closeAwakenedMimic(owner.state, day);
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_mimic_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== "awakened_mimic") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (
          !owner.isCurrent() ||
          !canAwakenedMimic(owner.state, day) ||
          !valid.ok ||
          valid.sanitizedCall?.name !== "awakened_mimic"
        )
          continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = candidates.get(targetId),
          origin = roles.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target) ||
          !origin ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== origin.component ||
          origin.component.role !== origin.role ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== origin.camp
        )
          continue;
        if (!learnAwakenedRole(owner.state, targetId, origin.role, day)) continue;
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimicked",
          payload: { actorId: owner.actorId, day, targetId, role: owner.state.learned!.role },
        });
        completed = true;
        break;
      }
      if (!completed && owner.isCurrent() && canAwakenedMimic(owner.state, day)) {
        if (targets(ctx, owner.actorId, true).size)
          throw new Error("awakened_mimic_valid_action_missing");
        closeAwakenedMimic(owner.state, day);
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_mimic_skipped",
          payload: { actorId: owner.actorId, day },
        });
      }
    }
  },
};

const skillStage: NightStageHandler = {
  id: "awakened_skill",
  priority: 650,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day),
        skill = bound?.skill;
      if (!bound || !skill || skill.kind === "wolf") continue;
      const tool: ToolName = skill.kind === "poison" ? "awakened_poison" : "awakened_guard";
      const current = () => bound.isCurrent() && awakenedSkillForNight(owner.state, day) === skill;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, [tool], {
            stage: "awakened_skill",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        if (action === null) {
          if (!skipAwakenedSkill(owner.state, day)) break;
          recordAwakenedNightCommit(ctx.world, day);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_skill_skipped",
            payload: { actorId: owner.actorId, day },
          });
          completed = true;
          break;
        }
        if (action.name !== tool) continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || !valid.sanitizedCall) continue;
        const call = valid.sanitizedCall;
        if (call.name !== "awakened_poison" && call.name !== "awakened_guard") continue;
        const targetId = call.args.target_id,
          target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (call.name === "awakened_poison" && skill.kind === "poison" && target) {
          if (!useAwakenedPoison(owner.state, day)) break;
          (ctx.state.poisonClaims ??= []).push(
            originalPoisonIntent(
              {
                source: owner.life,
                target,
                isCurrent: () => bound.isCurrent(true),
              },
              {
                family: "awakened",
                day,
                stage: "awakened_skill",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
          ctx.ensureMarks(target.id).add(StatusMark.PoisonMark);
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_poison_used",
            payload: { actorId: owner.actorId, day, targetId: target.id },
          });
        } else if (call.name === "awakened_guard" && skill.kind === "guard") {
          if (!chooseAwakenedGuard(owner.state, targetId, day)) continue;
          if (target)
            effects(ctx).shields.push(
              awakenedNightIntent(
                "awakened-shield",
                {
                  actorId: owner.actorId,
                  target,
                  isCurrent: () => bound.isCurrent(true),
                },
                {
                  family: "awakened",
                  day,
                  stage: "awakened_skill",
                  actorLife: owner.life,
                  requestedTargetId: targetId,
                  abilityId: "learned:awakened",
                },
              ),
            );
          ctx.events.push({
            timestamp: Date.now(),
            type: "awakened_guard_chosen",
            payload: { actorId: owner.actorId, day, targetId },
          });
        } else continue;
        recordAwakenedNightCommit(ctx.world, day);
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_skill_valid_action_missing");
    }
  },
};

const attackStage: NightStageHandler = {
  id: "awakened_attack",
  priority: 660,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const bound = bindAwakenedSkill(owner, day);
      if (bound?.skill.kind !== "wolf") continue;
      const effectCurrent = () => bound.isCurrent() && canAwakenedKnife(owner.role, ctx.world, () => ctx.world.getComponent(owner.actorId, COMPONENT.Camp));
      const current = () => effectCurrent() && canAwakenedExtraKnife(owner.state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const candidates = targets(ctx, owner.actorId, false);
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(owner.actorId, ["awakened_attack"], {
            stage: "awakened_attack",
            requiresAction: false,
            action_failure_policy: "error",
            allow_fallback: false,
            ...retry(attempt),
          }),
        );
        if (!current()) break;
        let targetId: number | null = null;
        if (action !== null) {
          if (action.name !== "awakened_attack") continue;
          const valid = ctx.toolGateway.validateAndSanitize(ctx.world, owner.actorId, action, {
            phase: Phase.Night,
            day,
          });
          if (!current() || !valid.ok || valid.sanitizedCall?.name !== "awakened_attack") continue;
          targetId = valid.sanitizedCall.args.target_id;
        }
        const target = targetId === null ? null : candidates.get(targetId);
        if (targetId !== null && (!target || !livingNightLife(ctx.world, target))) continue;
        if (!chooseAwakenedAttack(owner.state, targetId, day)) break;
        if (target)
          effects(ctx).attacks.push(
            awakenedNightIntent(
              "awakened-attack",
              { actorId: owner.actorId, target, isCurrent: effectCurrent },
              {
                family: "awakened",
                day,
                stage: "awakened_attack",
                actorLife: owner.life,
                requestedTargetId: targetId,
                abilityId: "learned:awakened",
              },
            ),
          );
        recordAwakenedNightCommit(ctx.world, day);
        ctx.events.push({
          timestamp: Date.now(),
          type: "awakened_attack_chosen",
          payload: { actorId: owner.actorId, day, targetId },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("awakened_attack_valid_action_missing");
    }
  },
};

const activationStage: NightStageHandler = {
  id: "awakened_activation",
  priority: 900,
  async execute(ctx) {
    const day = ctx.currentDay();
    for (const owner of owners(ctx, day)) {
      const learned = owner.state.learned;
      if (!learned || learned.activationNight !== null || !owner.isCurrent()) continue;
      let abilityId: string | undefined;
      if (learned.skill.kind === "inspection") {
        if (
          allNightAbilities(owner.role).some(
            (ability) => ability.kind === "role_check" && ability.source.kind === "native",
          ) ||
          retiredNightAbilityIds(owner.role).some((id) => id.startsWith("native:role_check"))
        )
          throw new Error("awakened_mirror_native_binding_conflict");
        installNativeAbility(owner.role, "role_check", {
          policy: "mirror",
          lastTarget: null,
          lastDay: null,
          history: [],
        });
        const ability = findNightAbility(owner.role, "role_check")!;
        setNightAbilityStartDay(ability, day + 1);
        abilityId = ability.id;
      }
      if (
        !owner.isCurrent() ||
        owner.state.learned !== learned ||
        !activateAwakenedLearning(owner.state, day, abilityId)
      )
        throw new Error("awakened_activation_commit_invalid");
      recordAwakenedNightCommit(ctx.world, day);
      ctx.events.push({
        timestamp: Date.now(),
        type: "awakened_ready",
        payload: {
          actorId: owner.actorId,
          activationNight: day,
          activeFromNight: day + 1,
          role: learned.role,
        },
      });
    }
  },
};

export const AWAKENED_NIGHT_STAGES = [
  openingStage,
  mimicStage,
  skillStage,
  attackStage,
  activationStage,
];

/**
 * 负责觉醒隐狼的工具资格校验贡献。输入为原工具参数、角色状态及可信窗口，输出原规则拒绝或通过。
 * 当前原体、学习／盾／刀资格仍归实际机制，本校验不执行学习、消费库存或提交死亡。
 */
import { AWAKENED_TOOL_NAMES } from "./tool_names";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { isAliveTarget, type ToolRule, type ToolRuleMap } from "../../validation/contracts";
import { canAwakenedKnife } from "./inheritance";
import { currentAwakenedNight } from "./night_scope";
import {
  awakenedSkillForNight,
  canAwakenedExtraKnife,
  canAwakenedMimic,
  getAwakenedState,
} from "./state";

const validateAwakened: ToolRule = ({ world, actorId, role, phase, day, toolCall }) => {
  const state = getAwakenedState(role);
  if (
    role.role !== Role.AwakenedHiddenWolf ||
    world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
    !state ||
    day === undefined ||
    currentAwakenedNight(world, role) !== day
  )
    return { code: RuleError.AwakenedUnavailable };
  if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
  if (toolCall.name === "awakened_mimic") {
    if (!canAwakenedMimic(state, day)) return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id !== actorId && isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  const skill = awakenedSkillForNight(state, day);
  if (toolCall.name === "awakened_attack") {
    if (!canAwakenedKnife(role, world, () => world.getComponent(actorId, COMPONENT.Camp)) || !canAwakenedExtraKnife(state, day))
      return { code: RuleError.AwakenedUnavailable };
    return toolCall.args.target_id === null || isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  }
  if (toolCall.name === "awakened_poison" && skill?.kind === "poison")
    return isAliveTarget(world, toolCall.args.target_id)
      ? null
      : { code: RuleError.AwakenedTarget };
  if (toolCall.name === "awakened_guard" && skill?.kind === "guard") {
    if (toolCall.args.target_id !== null && !isAliveTarget(world, toolCall.args.target_id))
      return { code: RuleError.AwakenedTarget };
    if (
      toolCall.args.target_id !== null &&
      skill.lastTarget === toolCall.args.target_id &&
      skill.lastGuardDay === day - 1
    )
      return { code: RuleError.AwakenedGuardRepeat };
    return null;
  }
  return { code: RuleError.AwakenedUnavailable };
};
export { AWAKENED_TOOL_NAMES } from "./tool_names";
export const AWAKENED_VALIDATION_RULES: ToolRuleMap = Object.fromEntries(
  AWAKENED_TOOL_NAMES.map((name) => [name, validateAwakened]),
);

/**
 * 负责机械狼的学习模板、所属槽安装、模式／刀资源提交和玩家投影。输入为原角色、状态与日次；
 * 输出保留原学习、模式、刀权字段以及存储引用，公开 DTO 类型独立归公共契约。
 * 模板创建不克隆其他玩家库存；本模块只写 mechanical_wolf 及其资源，不替换角色容器或授予请求许可。
 * 实际开夜才武装枪和处理首刀过期；提交按原字段顺序，异常不回滚此前状态。
 */
import type {
  MechanicalMode,
  MechanicalSkill,
  MechanicalLearning,
  MechanicalState,
  MechanicalReadSkill,
  MechanicalReadLearning,
  MechanicalReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerMechanicalState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { InspectionResult, RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";
import { createLearnedNativeGun, armMechanicalNativeGun } from "../native-death-gun-resources";

export function freshMechanicalState(): MechanicalState {
  return {
    learned: null,
    mimicClosedDay: null,
    mode: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
    skillClosedDay: null,
  };
}
/** 从所属槽返回原存储引用；类型只读不等于复制或运行时冻结，写入仍由具名提交函数负责。 */
export function getMechanicalState(
  role: RoleComponent | undefined,
): MechanicalReadState | undefined {
  return (role as { readonly privateState: { readonly mechanical_wolf?: unknown } } | undefined)
    ?.privateState.mechanical_wolf as MechanicalReadState | undefined;
}
export function setMechanicalState(
  role: RoleComponent,
  state: MechanicalState,
): MechanicalReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { mechanical_wolf: MechanicalState }).mechanical_wolf = owned;
  return owned;
}
export function mechanicalLearning(
  targetId: EntityId,
  role: RoleId,
  day: number,
): MechanicalLearning {
  let skill: MechanicalSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "psychic":
      skill = { kind: "inspection", history: [] };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = createLearnedNativeGun();
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("mechanical_learning_role_not_supported");
  }
  return { targetId, role, day, readyOnNight: day + 1, skill };
}

/** 开局／死亡检查点调用此处一次提交继承字段；后续刀权资格和事实发布仍由原调用方负责。 */
export function recordMechanicalInheritance(state: MechanicalReadState, day: number): boolean {
  if (state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}

export function canMechanicalMimic(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 1 &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}

/** 合法等待只关闭本夜学习机会，保留整局一次的学习库存。 */
export function closeMechanicalMimic(state: MechanicalReadState, day: number): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

export function learnMechanicalRole(
  state: MechanicalReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
): boolean {
  if (!canMechanicalMimic(state, day)) return false;
  const learned = mechanicalLearning(targetId, role, day);
  if (
    learned.skill.kind === "wolf" &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  (state as { learned: MechanicalReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 进入实际夜才武装被动枪，并将已经过去的首刀窗口标为过期，不能靠日次跳转补刀。 */
export function advanceMechanicalNight(state: MechanicalReadState, day: number): void {
  const learned = state.learned;
  if (!learned) return;
  armMechanicalNativeGun(learned, day);
  if (
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available" &&
    state.firstKnifeNight !== null &&
    day > state.firstKnifeNight
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
}

export function canSelectMechanicalMode(state: MechanicalReadState, day: number): boolean {
  return day >= 2 && (state.mode === null || state.mode.day < day);
}

/** 等待沿用技能模式选择；本夜第二次选择被拒，不重写第一次模式。 */
export function selectMechanicalMode(
  state: MechanicalReadState,
  day: number,
  mode: MechanicalMode,
): boolean {
  if (!canSelectMechanicalMode(state, day)) return false;
  (state as { mode: MechanicalReadState["mode"] }).mode = { day, kind: mode };
  const learned = state.learned;
  if (
    mode === "skill" &&
    state.firstKnifeNight === day &&
    learned?.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  ) {
    (learned.skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = "expired";
  }
  return true;
}

export function mechanicalSkillForNight(
  state: MechanicalReadState,
  day: number,
): MechanicalReadSkill | undefined {
  if (
    day < 2 ||
    state.mode?.day !== day ||
    state.mode.kind !== "skill" ||
    !state.learned ||
    state.learned.readyOnNight > day ||
    (state.skillClosedDay !== null && state.skillClosedDay >= day)
  )
    return undefined;
  return state.learned.skill;
}

export function closeMechanicalSkill(state: MechanicalReadState, day: number): boolean {
  if (!mechanicalSkillForNight(state, day)) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = day;
  return true;
}

/** 调用方另行核对当前唯一活狼的刀权及原模式许可；本字段查询不授予出刀资格。 */
export function mechanicalKnifeSelected(state: MechanicalReadState, day: number): boolean {
  return (
    day >= 2 &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    day >= state.firstKnifeNight &&
    state.mode?.day === day &&
    state.mode.kind === "kill"
  );
}

export function canMechanicalExtraKnife(state: MechanicalReadState, day: number): boolean {
  const learned = state.learned;
  return (
    mechanicalKnifeSelected(state, day) &&
    state.firstKnifeNight === day &&
    learned !== null &&
    learned.readyOnNight <= day &&
    learned.skill.kind === "wolf" &&
    learned.skill.extraKnife === "available"
  );
}

/** 按相邻实际夜与目标编号判重复守护，同编号复活不会清除该历史；两字段按原顺序写入。 */
export function chooseMechanicalGuard(
  skill: Extract<MechanicalReadSkill, { kind: "guard" }>,
  targetId: EntityId | null,
  day: number,
): { failed: boolean } {
  const failed =
    targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === day - 1;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = day;
  return { failed };
}

/** 玩家投影逐字段列出知识和资源摘要；以后新增的全局调试字段不会自动成为玩家输入。 */
export function projectMechanicalState(state: MechanicalReadState): PlayerMechanicalState {
  const learned = state.learned;
  let skill: MechanicalSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = {
          kind: "inspection",
          history: learned.skill.history.map((report) => ({
            day: report.day,
            targetId: report.targetId,
            result: { kind: "role", role: report.result.role },
          })),
        };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", canShoot: learned.skill.canShoot, armed: learned.skill.armed };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            readyOnNight: learned.readyOnNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    mode: state.mode ? { day: state.mode.day, kind: state.mode.kind } : null,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
    skillClosedDay: state.skillClosedDay,
  };
}

/** 调用方保留查验与当前性检查；先读取原历史容器，再读取 target.id 并追加一行。 */
export function recordMechanicalInspection(
  skill: Extract<MechanicalReadSkill, { kind: "inspection" }>,
  day: number,
  target: { readonly id: EntityId },
  result: Extract<InspectionResult, { kind: "role" }>,
): void {
  (skill.history as Extract<MechanicalSkill, { kind: "inspection" }>["history"]).push({
    day,
    targetId: target.id,
    result: { ...result },
  });
}
/** 原毒提案与标记之后提交库存消耗，不增加复检、回滚或新的付款时点。 */
export function consumeMechanicalPoison(
  skill: Extract<MechanicalReadSkill, { kind: "poison" }>,
): void {
  (skill as { remaining: 0 | 1 }).remaining = 0;
}
/** 调用方保留原攻击可空目标与完成顺序；非空目标标花费，空目标只按原机械首刀规则过期。 */
export function closeMechanicalExtraKnife(
  skill: Extract<MechanicalReadSkill, { kind: "wolf" }>,
  target: unknown,
): void {
  (skill as { extraKnife: "available" | "spent" | "expired" }).extraKnife = target
    ? "spent"
    : "expired";
}

/**
 * 负责觉醒隐狼的学习模板、所属槽安装、激活／技能资源提交和玩家投影。输入为原角色、状态与实际夜；
 * 输出保留激活、技能和原存储引用，公开 DTO 类型独立归公共契约。
 * 只写 awakened_hidden_wolf 及其学习资源，不扩大角色容器写权、重抽模板、退款或授予请求许可。
 * 激活与主动技能生效夜分别保存；次数／关窗和字段提交保持原顺序，失败保留已写前缀。
 */
import type {
  AwakenedSkill,
  AwakenedActiveSkill,
  AwakenedTemplateRole,
  AwakenedLearning,
  AwakenedState,
  AwakenedReadSkill,
  AwakenedReadActiveSkill,
  AwakenedReadLearning,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";

import type { PlayerAwakenedState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleId } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "../../../../core/domain/identity";
import { copyAbilityData } from "../abilities";
import { createLearnedNativeGun, armAwakenedNativeGun } from "../native-death-gun-resources";

const validDay = (day: number) =>
  Number.isSafeInteger(day) && day >= 1 && day < Number.MAX_SAFE_INTEGER;
const validTarget = (id: number) => Number.isSafeInteger(id) && id >= 1;
export function freshAwakenedState(): AwakenedState {
  return {
    learned: null,
    mimicClosedDay: null,
    skillClosedDay: null,
    hasInheritedKnife: false,
    firstKnifeNight: null,
  };
}
export function getAwakenedState(role: RoleComponent | undefined): AwakenedReadState | undefined {
  return (
    role as { readonly privateState: { readonly awakened_hidden_wolf?: unknown } } | undefined
  )?.privateState.awakened_hidden_wolf as AwakenedReadState | undefined;
}
/** 复制数据后安装到原私有槽；请求许可和原体证明另有所有者，不随此数据复制。 */
export function setAwakenedState(role: RoleComponent, state: AwakenedState): AwakenedReadState {
  const owned = copyAbilityData(state);
  (role.privateState as { awakened_hidden_wolf: AwakenedState }).awakened_hidden_wolf = owned;
  return owned;
}

export function awakenedLearning(targetId: EntityId, role: RoleId, day: number): AwakenedLearning {
  if (!validDay(day) || !validTarget(targetId)) throw new Error("awakened_learning_input_invalid");
  let skill: AwakenedSkill;
  switch (role) {
    case "villager":
      skill = { kind: "villager" };
      break;
    case "mirror_girl":
      skill = { kind: "inspection", abilityId: null };
      break;
    case "witch":
      skill = { kind: "poison", remaining: 1 };
      break;
    case "guard":
      skill = { kind: "guard", lastTarget: null, lastGuardDay: null };
      break;
    case "hunter":
      skill = createLearnedNativeGun();
      break;
    case "wolf":
      skill = { kind: "wolf", extraKnife: "available" };
      break;
    default:
      throw new Error("awakened_learning_role_not_supported");
  }
  return { targetId, role, day, activationNight: null, activeFromNight: null, skill };
}
export function canAwakenedMimic(state: AwakenedReadState, day: number): boolean {
  return (
    validDay(day) &&
    state.learned === null &&
    (state.mimicClosedDay === null || state.mimicClosedDay < day)
  );
}
export function closeAwakenedMimic(state: AwakenedReadState, day: number): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}
export function learnAwakenedRole(
  state: AwakenedReadState,
  targetId: EntityId,
  role: RoleId,
  day: number,
): boolean {
  if (!canAwakenedMimic(state, day)) return false;
  const learned = awakenedLearning(targetId, role, day);
  (state as { learned: AwakenedReadState["learned"] }).learned = learned;
  (state as { mimicClosedDay: number | null }).mimicClosedDay = day;
  return true;
}

/** 只在实际夜末提交激活；选择模板或进入以后日次不会补造激活夜。 */
export function activateAwakenedLearning(
  state: AwakenedReadState,
  night: number,
  mirrorAbilityId?: string,
): boolean {
  const learned = state.learned;
  if (!learned || !validDay(night) || night < learned.day || learned.activationNight !== null)
    return false;
  if (
    learned.skill.kind === "inspection" &&
    (typeof mirrorAbilityId !== "string" || !mirrorAbilityId.length)
  )
    return false;
  if (learned.skill.kind !== "inspection" && mirrorAbilityId !== undefined) return false;
  if (learned.skill.kind === "inspection")
    (learned.skill as { abilityId: string | null }).abilityId = mirrorAbilityId!;
  armAwakenedNativeGun(learned);
  (learned as { activationNight: number | null }).activationNight = night;
  (learned as { activeFromNight: number | null }).activeFromNight = night + 1;
  return true;
}

/** 被动猎人枪的可用性从枪自身读取；主动技能要在实际激活后的生效夜查询。 */
export function awakenedSkillForNight(
  state: AwakenedReadState,
  night: number,
): AwakenedReadActiveSkill | undefined {
  const learned = state.learned;
  if (
    !validDay(night) ||
    !learned ||
    learned.activationNight === null ||
    learned.activeFromNight === null ||
    night < learned.activeFromNight ||
    (state.skillClosedDay !== null && state.skillClosedDay >= night)
  )
    return undefined;
  if (learned.skill.kind === "poison" && learned.skill.remaining === 0) return undefined;
  if (learned.skill.kind === "wolf" && learned.skill.extraKnife === "spent") return undefined;
  return learned.skill.kind === "poison" ||
    learned.skill.kind === "guard" ||
    learned.skill.kind === "wolf"
    ? learned.skill
    : undefined;
}
export function closeAwakenedSkill(state: AwakenedReadState, night: number): boolean {
  if (!awakenedSkillForNight(state, night)) return false;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 装配／死亡检查点一次提交继承；它不依赖学习或技能选择，不消费学习资源。 */
export function recordAwakenedInheritance(state: AwakenedReadState, day: number): boolean {
  if (!validDay(day) || state.hasInheritedKnife) return false;
  (state as { hasInheritedKnife: boolean }).hasInheritedKnife = true;
  (state as { firstKnifeNight: number | null }).firstKnifeNight = Math.max(2, day + 1);
  return true;
}
export function awakenedKnifeReady(state: AwakenedReadState, night: number): boolean {
  return (
    validDay(night) &&
    state.hasInheritedKnife &&
    state.firstKnifeNight !== null &&
    night >= state.firstKnifeNight
  );
}
/** 调用方还核对当前原持有者与唯一活狼许可；这里的字段条件不单独授予刀权。 */
export function canAwakenedExtraKnife(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  return (
    awakenedKnifeReady(state, night) && skill?.kind === "wolf" && skill.extraKnife === "available"
  );
}
/** 空刀只关闭本夜机会；实际非空攻击才花费整局一次的额外刀库存。 */
export function chooseAwakenedAttack(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
): boolean {
  if (!canAwakenedExtraKnife(state, night) || (targetId !== null && !validTarget(targetId)))
    return false;
  const skill = state.learned!.skill;
  if (skill.kind !== "wolf") return false;
  if (targetId !== null) (skill as { extraKnife: "available" | "spent" }).extraKnife = "spent";
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

export function chooseAwakenedGuard(
  state: AwakenedReadState,
  targetId: EntityId | null,
  night: number,
): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (
    skill?.kind !== "guard" ||
    (targetId !== null && !validTarget(targetId)) ||
    (targetId !== null && skill.lastTarget === targetId && skill.lastGuardDay === night - 1)
  )
    return false;
  (skill as { lastTarget: EntityId | null }).lastTarget = targetId;
  (skill as { lastGuardDay: number | null }).lastGuardDay = night;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}
/** 合法的无工具等待也按空目标结束本夜守护，打断连续守同一编号的历史。 */
export function skipAwakenedSkill(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (!skill) return false;
  if (skill.kind === "guard") return chooseAwakenedGuard(state, null, night);
  if (skill.kind === "wolf") return chooseAwakenedAttack(state, null, night);
  return closeAwakenedSkill(state, night);
}
export function useAwakenedPoison(state: AwakenedReadState, night: number): boolean {
  const skill = awakenedSkillForNight(state, night);
  if (skill?.kind !== "poison" || skill.remaining !== 1) return false;
  (skill as { remaining: 0 | 1 }).remaining = 0;
  (state as { skillClosedDay: number | null }).skillClosedDay = night;
  return true;
}

/** 只投影列出的玩家字段；魔镜查验历史与库存由其能力实例唯一拥有，不复制进学习模板。 */
export function projectAwakenedState(state: AwakenedReadState): PlayerAwakenedState {
  const learned = state.learned;
  let skill: AwakenedSkill | undefined;
  if (learned)
    switch (learned.skill.kind) {
      case "villager":
        skill = { kind: "villager" };
        break;
      case "inspection":
        skill = { kind: "inspection", abilityId: learned.skill.abilityId };
        break;
      case "poison":
        skill = { kind: "poison", remaining: learned.skill.remaining };
        break;
      case "guard":
        skill = {
          kind: "guard",
          lastTarget: learned.skill.lastTarget,
          lastGuardDay: learned.skill.lastGuardDay,
        };
        break;
      case "hunter":
        skill = { kind: "hunter", armed: learned.skill.armed, canShoot: learned.skill.canShoot };
        break;
      case "wolf":
        skill = { kind: "wolf", extraKnife: learned.skill.extraKnife };
        break;
    }
  return {
    learned:
      learned && skill
        ? {
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            activationNight: learned.activationNight,
            activeFromNight: learned.activeFromNight,
            skill,
          }
        : null,
    mimicClosedDay: state.mimicClosedDay,
    skillClosedDay: state.skillClosedDay,
    hasInheritedKnife: state.hasInheritedKnife,
    firstKnifeNight: state.firstKnifeNight,
  };
}

/**
 * 负责四族原生／学习死亡枪的数据创建、原槽安装、武装、捕获复验和库存消费。
 * 输入为原角色、原学习对象与晚取查询；输出保留同一槽／枪引用和原每次 hook 的捕获表。
 * 原生安装不克隆、不冻库存；学习模板仅创建自己的全新枪，已有整学习数据的复制仍由各族安装 owner 执行。
 * 本 owner 安装两个原生槽并写原枪字段，原体、生命、死因及请求许可仍在结算／具体权威复验；只读类型不是权限屏障。
 * 学习枪先晚取原查询并裸调用、读 skill，再在原阵营点调用显式 source；不存 Camp 引用。
 * 猎魔板子先捕获原审计库存，支付仍由同一权威执行；setter／编码或后续发表失败均不退款。
 */
import type { CurrentCampSource } from "../../../core/domain/components/camp";
import type {
  HunterState,
  HunterReadState,
  WolfKingState,
  WolfKingReadState,
  MechanicalReadState as MechanicalState,
  MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill,
  MechanicalReadState,
  AwakenedReadState as AwakenedState,
  AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill,
  AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import type { RoleInitContext } from "./contracts";
import type { openDemonHunterStockFrame } from "./demon_hunter/native-gun-ports";

/** 创建仍逐次读取原配置 getter，不缓存 boardConfig／policy；分支保持原字段可选性。 */
export function createHunterState(ctx: Pick<RoleInitContext, "boardConfig">): HunterState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
      : {}),
  };
}
export function createWolfKingState(ctx: Pick<RoleInitContext, "boardConfig">): WolfKingState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
    ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
      ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
      : {}),
